#include <sstream>
#include <queue>
#include <utility>
using namespace std;

int main(){
vector<double>logit={1.2,0.8,-0.4};
double temperature=0.8;
double largest=*max_element(logit.begin(),logit.end());
vector<double>probability(3);
double total=0;
for(int i=0;i<3;i++){
    probability[i]=exp((logit[i]-largest)/temperature);
    total+=probability[i];
}
double sampledUniform=0.7,cumulative=0;
for(int i=0;i<3;i++){
    cumulative+=probability[i]/total;
    if(sampledUniform<=cumulative){cout<<"next-token "<<i<<"\n";break;}
}
return 0;
}

