#include <sstream>
#include <queue>
#include <utility>
using namespace std;

int main(){
vector<vector<int>>graph={{1,2},{0,3},{0,4},{1},{2}};
vector<int>distance(graph.size(),-1);
queue<int>q;q.push(0);distance[0]=0;
while(!q.empty()){
    int u=q.front();q.pop();
    if(distance[u]>=2)continue;
    for(int v:graph[u])if(distance[v]==-1){
        distance[v]=distance[u]+1;q.push(v);
    }
}
for(int i=0;i<int(distance.size());i++)cout<<i<<" "<<distance[i]<<"\n";
return 0;
}

