#include <algorithm>
#include <iomanip>
#include <map>
#include <string>
#include <sstream>
#include <queue>
#include <utility>
using namespace std;

int main(){
vector<double>series={0.1,0.2,-0.1,0.05,0.3};
double mean=0,lag=0,variance=0;
for(double x:series)mean+=x/series.size();
for(int t=0;t<int(series.size());t++){
    variance+=pow(series[t]-mean,2);
    if(t>0)lag+=(series[t]-mean)*(series[t-1]-mean);
}
cout<<"ACF lag 1 "<<lag/variance<<"\n";
return 0;
}

